export function validConcept(x,projects){return x&&typeof x.projectName==='string'&&x.projectName.length<=160&&typeof x.summary==='string'&&x.summary.length<=4000&&typeof x.productType==='string'&&Array.isArray(x.coreSystems)&&x.coreSystems.length<=12&&x.coreSystems.every(s=>typeof s==='string'&&s.length<=250)&&Array.isArray(x.suggestedPhases)&&x.suggestedPhases.length<=4&&x.suggestedPhases.every(p=>p&&typeof p.name==='string'&&Array.isArray(p.items)&&p.items.every(s=>typeof s==='string'&&s.length<=250))&&Array.isArray(x.matchingProjectIds)&&x.matchingProjectIds.every(id=>projects.some(p=>p.id===id))&&typeof x.nextStep==='string'&&(!x.complexity||(Number.isInteger(x.complexity.score)&&x.complexity.score>=1&&x.complexity.score<=10&&['low','medium','high'].includes(x.complexity.level)&&typeof x.complexity.explanation==='string'))}